import{j as e}from"./index-05FmW9Lg.js";import{L as t,l as a}from"./LocationPage-DroLwcsj.js";import"./Breadcrumbs-Cz2W94SO.js";import"./building-2-DFzT8v4O.js";import"./info-ClmCH7sn.js";import"./circle-help-BJNhmzGP.js";const n={path:"/locations/united-arab-emirates",h1:"Software and AI Development for Businesses in the United Arab Emirates",valueProp:"An India-based software and AI development partner serving businesses in the UAE — close enough in time to share a working day, and remote in every other respect.",heroHighlights:["Delivered from Indore, India, for customers and internal teams across the UAE","A working day that overlaps yours for most of its length, without a fixed-hours promise","Mobile-first builds, booking and service platforms, dashboards and AI assistants","Arabic interface work available as a separately scoped piece of the project"],intro:["UAE projects usually begin with a customer who is already on a phone. Bookings, service requests, deliveries, appointments, memberships, loyalty — the business exists in an app or a browser first, and the internal systems have to keep up with what that front end promises. That is the shape of most work we take on for the region.","SCS Softwares works from Indore, India. The practical consequence for a UAE client is simple: there is only a small difference between our clock and yours, so a message sent mid-morning is answered mid-morning, and a demonstration can be scheduled in normal business hours for both sides without anybody staying late. We still do not publish a fixed availability window — what we commit to is agreed per engagement.","Delivery, documentation and meetings are conducted in English. Where an interface has to exist in Arabic as well, we treat that as a defined piece of scope with its own effort and its own review step, and the wording is supplied or approved on your side. Hosting location, integrations and privacy requirements are settled during discovery, before any system is designed around them."],disclosure:{title:"Delivered from India, not from the Emirates",body:"SCS Softwares operates from Indore, Madhya Pradesh, India, and serves UAE clients remotely from there. This page is about the availability of a service in the region — nothing more.",points:["We have no premises in Dubai, Abu Dhabi, Sharjah or anywhere else in the UAE, and no local office is represented here.","There is no UAE trade licence, no mainland or free-zone entity, and no local commercial registration behind this page.","Every part of delivery is remote: kick-off, design review, demonstrations and stakeholder approvals all happen online.","Nobody on the team is employed or resident in the UAE, and we make no claim to Emirati staff or representation.","We hold no government approval, listing or certification in the UAE, and we do not advise on local regulation."]},concerns:{eyebrow:"Early questions",heading:"What UAE clients want settled before work starts",intro:"These come up in the first or second conversation, and they are usually the things that decide whether a project runs smoothly.",items:[{title:"How quickly a customer-facing app can be in market",body:"Faster if the first release is genuinely a first release. We push hard for a narrow launch scope — the booking or ordering journey working end to end — and treat the rest of the wish list as a second phase with its own date."},{title:"Whether the app will work for a customer on a phone in Arabic",body:"Right-to-left layout, Arabic typography and bidirectional text are engineering work we can do, and we scope it explicitly. The Arabic wording itself is supplied or signed off by your side, because we do not present ourselves as an Arabic-language content team."},{title:"How payment, messaging and delivery integrations are handled",body:"Named during discovery, one by one: which gateway, which messaging channel, which logistics or POS system, and what happens when each of them fails. Integrations are where launch dates go, so they are scoped before the estimate."},{title:"Where the data will be hosted",body:"Chosen with you before the architecture is fixed. If your requirement is that data stays in a particular region, that constraint decides the hosting arrangement rather than being retrofitted afterwards."},{title:"How several stakeholders approve one build",body:"Most UAE projects we work on have an owner, an operations lead and a marketing view. We run demonstrations with all of them present and record decisions in writing, so approval does not travel by forwarded message."},{title:"Whether an AI assistant can be let near customers",body:"Within limits we agree first. The assistant answers from your own material, can take only the actions we defined, and hands the conversation to a person when it is outside that boundary."}]},services:{eyebrow:"What we build",heading:"The services most UAE projects draw on",intro:"Each page below covers a service in full and stays country-neutral. This page is about how those services are delivered to the region from India.",items:[{path:"/services/mobile-app-development",label:"Mobile App Development",blurb:"The centre of most UAE builds: a customer app on iOS and Android, with payments, notifications, maps and an Arabic interface where the audience needs one."},{path:"/services/web-application-development",label:"Web Application Development",blurb:"Booking and service platforms, customer accounts, branch and franchise dashboards, and the admin tools your operations team works in daily."},{path:"/services/custom-software-development",label:"Custom Software Development",blurb:"Internal business systems for scheduling, dispatch, inventory or approvals, replacing whatever combination of sheets and messaging is holding it together now."},{path:"/services/saas-development",label:"SaaS Development",blurb:"A product sold to other businesses in the region: tenants, subscription plans, entitlements and the reporting an account manager needs."},{path:"/services/software-modernization",label:"Software Modernization",blurb:"A rework of an app or portal that launched years ago and no longer matches the brand, the phone screens or the volume it now handles."},{path:"/services/ai-development",label:"AI Development",blurb:"Assistants answering from your service catalogue, price list or policy documents, with retrieval, logging and a defined escalation to your staff."},{path:"/services/ai-voice-agent-development",label:"AI Voice Agent Development",blurb:"Spoken assistants inside your app or website for enquiries, availability and booking status, with interruption handling and a handover path."},{path:"/services/ai-video-consultation-agents",label:"AI Video Consultation Agents",blurb:"A guided video consultation that gathers a customer brief or intake details and produces a structured summary your team reviews afterwards."},{path:"/services/ai-automation-integration",label:"AI Automation & Integration",blurb:"Automating the back office behind the app: quotations, invoices, document checks and approvals, connected to the systems you already run."}]},projectTypes:{eyebrow:"Project fit",heading:"The UAE builds this suits",intro:"These are the project shapes that have worked well delivered remotely from Indore for clients in the region.",items:[{title:"A booking or service app with real availability behind it",body:"Salons, clinics, maintenance, rentals, fitness, home services. The visible part is a booking flow; the actual work is availability, staff rosters, cancellations and the payment path."},{title:"A customer app on top of an existing shopfront business",body:"A business with branches and no digital channel. The app handles ordering or appointments, and the back office gets a dashboard instead of a stack of printed slips."},{title:"A multi-branch operations dashboard",body:"One view across locations: today’s volume, staff allocation, stock, exceptions. Built so a regional manager can compare branches without asking each one for a report."},{title:"A bilingual customer-facing platform",body:"English and Arabic interfaces from the same codebase, with right-to-left layout handled properly rather than mirrored by hand at the end of the project."},{title:"An AI assistant on the front of a service business",body:"Answering availability, pricing and process questions from your own documents at any hour, and passing anything outside its defined scope to a person the next morning."},{title:"Automation of a paperwork-heavy internal process",body:"Quotation approvals, supplier documents, delivery notes or claim forms moving between people. The reading and routing is automated; the approval stays human."}]},collaboration:{eyebrow:"How we work together",heading:"From first conversation to a live product",intro:"Because the working days overlap, most of this happens in live conversation and is then confirmed in writing — rather than the other way round.",steps:[{title:"Discovery call with the people who decide",body:"One call with the owner and whoever runs operations. We would rather hear how the business currently handles a booking or an order than read a feature list.",points:["Scheduled inside normal business hours for both sides","The current manual process walked through, step by step","A clear statement if what you need is not something we should build"]},{title:"Scope, screens and integration list",body:"A written scope with the customer journeys, the admin screens, the integrations named individually, and the language requirements settled.",points:["Launch scope separated from the second phase, in writing","Payment, messaging and logistics integrations listed by name","Arabic interface work priced as its own line rather than assumed"]},{title:"Design agreed on the phone screen first",body:"Interface work starts at mobile width, because that is where your customers are. Layouts are reviewed in a shared session and approved before build.",points:["Mobile layouts reviewed before any desktop view is drawn","Right-to-left behaviour checked at design stage where Arabic is in scope","Brand, imagery and tone confirmed with your marketing side"]},{title:"Build cycles and remote demonstrations",body:"Short cycles, each ending in a demonstration on a real device with all stakeholders present, and a written note of what was approved and what changed.",points:["A test build installable on your own phones each cycle","Stakeholder approvals recorded after each demonstration","Changes sized and confirmed in writing before they are built"]},{title:"Launch, monitoring and the next phase",body:"Store submission, production deployment, and a monitored first weeks. Then a decision about phase two or a handover to whoever will run it.",points:["App store and production release prepared to an agreed checklist","Monitoring and error reporting in place before launch day","Repositories, accounts, credentials and documentation handed to you"]}]},communication:{eyebrow:"Time zones",heading:"A working day that mostly lines up",intro:"Indian Standard Time sits an hour and a half ahead of Gulf Standard Time, which is the smallest gap between us and any of the nine markets on this site. In practice that means a shared working day rather than a handover window, though we still commit to specifics per project rather than in general.",points:["Most of your working hours fall inside ours, so questions are usually answered the same morning or afternoon.","The recurring meeting slot is agreed at kick-off in Gulf time and held for the length of the engagement.","We state the availability we are committing to in the engagement rather than implying continuous cover.","The Indian and UAE working weeks differ at the weekend; we agree which days are shared before the schedule is set.","Demonstrations run on video with all stakeholders present, and decisions are written up the same day.","Everyday communication happens on whichever channel your team already uses, with the decisions mirrored into writing."],note:"We do not operate a UAE telephone line, and we do not claim availability outside the hours agreed in your engagement. Anything urgent follows the escalation contact set at kick-off."},security:{eyebrow:"Data and integrations",heading:"Hosting, privacy and access, decided before build",intro:"For a customer-facing product these decisions shape the architecture, so they are made during discovery rather than at launch.",points:["Hosting region is chosen with you and recorded in the agreement before the architecture is fixed.","Customer personal data stays out of development environments; we build against masked or generated records.","Payment handling is delegated to the gateway wherever possible, so card data does not sit in your application.","Access to production is per person, logged, and removed when someone leaves the project.","API keys and credentials are exchanged through a secret store, never through a chat thread.","Retention, export and deletion behaviour is written into the scope as a requirement."],note:"We hold no security certification and no regulatory approval in the UAE, and we do not describe the result as compliant with any local framework. If your sector imposes hosting, residency or record-keeping rules, bring them into discovery: we will build to what your advisers specify and document what we implemented so they can check it."},oversight:{title:"Keeping a person in front of the customer",body:"An AI assistant on a consumer-facing service will be asked things nobody anticipated. The design assumption is that it will sometimes be wrong, so the escape route is built at the same time as the feature.",points:["The assistant answers from your own catalogue, pricing and policy material rather than from general knowledge.","It can perform only the actions we defined — checking availability, creating a request — and nothing beyond them.","Anything involving a refund, a discount or a customer record goes to a person for approval.","Conversations are logged so a bad answer can be found, traced and corrected rather than argued about.","The handover to your staff is designed into the flow, with the context carried across."]},engagement:{eyebrow:"Commercials",heading:"How UAE engagements are usually arranged",intro:"Which shape fits depends on whether you are launching something new or extending something that already earns.",options:[{name:"Launch package",body:"A defined first release — customer app or platform, admin dashboard, the named integrations — priced against a written scope with milestone payments.",bestFor:"Best for a first digital channel that needs to be live by a specific season or date."},{name:"Phased product roadmap",body:"Launch first, then agreed phases: Arabic interface, loyalty, second city, AI assistant. Each phase is scoped and priced when it starts, not guessed at now.",bestFor:"Best when the business will learn from the first release before deciding the next."},{name:"Ongoing product support",body:"A monthly arrangement covering store updates, platform changes, monitoring, small improvements and an agreed route for raising issues.",bestFor:"Best for a live app that needs to keep working while the business grows around it."}]},faqs:[{question:"Do you have a Dubai or Abu Dhabi office?",answer:"No. SCS Softwares works from Indore, India, and serves UAE clients remotely from there. We hold no UAE trade licence, no free-zone or mainland entity, no Emirates address and no local telephone number, and we will not present a market page as if we did."},{question:"Can you deliver the app in Arabic as well as English?",answer:"We build the bilingual interface — right-to-left layout, Arabic typography, bidirectional text and language switching — and scope it as its own piece of work with its own effort. The Arabic wording is supplied or approved on your side. We do not describe ourselves as an Arabic-speaking team, and copy we have not had reviewed by your people does not ship."},{question:"How different are our working hours?",answer:"Gulf Standard Time is an hour and a half behind Indian Standard Time, so the working days largely coincide and most questions are answered within the same session. The weekend differs, so we agree at kick-off which days are shared and what availability we are committing to for your project."},{question:"Which payment gateways and local services can you integrate?",answer:"We integrate whatever your bank or provider supports and documents, and we name each integration during discovery rather than promising a generic list. Where a provider’s documentation or test environment is weak, we say so early, because that is what usually moves a launch date."},{question:"Can data stay hosted in the region?",answer:"Yes, where your chosen cloud provider offers a suitable region. Hosting location is decided during discovery, before the architecture is settled, and written into the agreement. If your requirement is that nothing leaves a particular jurisdiction, that becomes a constraint on the design rather than a note at the end."},{question:"Do you handle UAE licensing, regulatory or legal requirements?",answer:"No. We are a development supplier, not an adviser on Emirati regulation, licensing or tax. We hold no government approval or certification in the UAE. Where a rule affects the software, tell us what your legal or compliance adviser requires and we will build to it."},{question:"How do we run demonstrations with several stakeholders?",answer:"On a scheduled video call with everyone who has an opinion present, using a build installed on your own devices. We write up what was agreed the same day, because a decision that only exists in a group chat tends to be remembered three different ways."}],otherMarkets:[{path:"/locations/united-states",label:"United States",blurb:"A much larger time-zone gap, handled with an agreed overlap window, a written scope and a clickable build every cycle."},{path:"/locations/united-kingdom",label:"United Kingdom",blurb:"A shared afternoon, documented requirements with acceptance criteria, and maintenance terms agreed before launch."},{path:"/locations/canada",label:"Canada",blurb:"Business platforms and portals where the first question is availability, and the second is what counts as accepted."},{path:"/locations/australia",label:"Australia",blurb:"Booking platforms, apps and dashboards, with test environments and a maintenance scope agreed ahead of go-live."},{path:"/locations/singapore",label:"Singapore",blurb:"Multi-entity operations platforms and document automation, run across a two-and-a-half-hour gap that never moves."},{path:"/locations/germany",label:"Germany",blurb:"Internal systems and modernization work, bought against a written specification and handed over with its test results."},{path:"/locations/netherlands",label:"Netherlands",blurb:"Platforms whose value sits in the connections between existing systems rather than in a new customer-facing application."},{path:"/locations/turkey",label:"Turkey",blurb:"Another consumer-app market, with Turkish interface engineering and marketplace settlement logic in place of right-to-left layout work."}],cta:{title:"Tell us what your customer is trying to do on their phone",body:"Get an indicative estimate from a few questions, walk through the idea with our AI consultation agent, or send the details to the team in Indore and we will come back with a scope."}},l=()=>e.jsx(t,{content:a(n)});export{l as default};
